import React, { useState } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Brush,
  ReferenceLine,
  Area,
  AreaChart,
  ComposedChart
} from 'recharts';

// Fungsi helper untuk memformat tanggal
const formatDate = (dateString) => {
  const date = new Date(dateString);
  // Cek apakah tanggal valid
  if (isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
};

// Fungsi helper untuk memformat angka sebagai mata uang
const formatCurrency = (value, currencySymbol = 'Rp') => {
  if (typeof value !== 'number') return '-';
  return `${currencySymbol} ${value.toLocaleString('id-ID')}`;
};

// Custom Tooltip komponen
const CustomTooltip = ({ active, payload, label, currencySymbol }) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;

    // Hitung perubahan harga dari titik sebelumnya jika tersedia
    const priceChange = data.previousClose ? data.Close - data.previousClose : 0;
    const percentChange = data.previousClose ? (priceChange / data.previousClose) * 100 : 0;
    const isPositive = priceChange >= 0;

    return (
        <div className="custom-tooltip bg-white p-4 border rounded-lg shadow-md" style={{
          border: `1px solid ${isPositive ? 'rgba(76, 175, 80, 0.3)' : 'rgba(229, 57, 53, 0.3)'}`,
          borderRadius: '8px',
          minWidth: '250px'
        }}>
          <p className="font-bold mb-2 pb-2 text-base" style={{
            borderBottom: '1px solid #eee',
            color: isPositive ? '#2E7D32' : '#C62828'
          }}>
            {formatDate(data.Date || data.Datetime)}
          </p>
          <div className="text-sm">
            <p className="flex justify-between my-1">
              <span className="mr-4 text-gray-600 font-medium">Buka:</span>
              <span className="font-semibold">{formatCurrency(data.Open, currencySymbol)}</span>
            </p>
            <p className="flex justify-between my-1">
              <span className="mr-4 text-gray-600 font-medium">Tertinggi:</span>
              <span className="font-semibold">{formatCurrency(data.High, currencySymbol)}</span>
            </p>
            <p className="flex justify-between my-1">
              <span className="mr-4 text-gray-600 font-medium">Terendah:</span>
              <span className="font-semibold">{formatCurrency(data.Low, currencySymbol)}</span>
            </p>
            <p className="flex justify-between my-1 px-2 py-1 rounded" style={{
              backgroundColor: isPositive ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)'
            }}>
              <span className="mr-4 text-gray-600 font-medium">Tutup:</span>
              <span className="font-bold text-base" style={{ color: isPositive ? '#2E7D32' : '#C62828' }}>
              {formatCurrency(data.Close, currencySymbol)}
            </span>
            </p>
            {data.previousClose && (
                <p className="flex justify-between my-1">
                  <span className="mr-4 text-gray-600 font-medium">Perubahan:</span>
                  <span className="font-semibold" style={{ color: isPositive ? '#2E7D32' : '#C62828' }}>
                {isPositive ? '+' : ''}{formatCurrency(priceChange, currencySymbol)} ({isPositive ? '+' : ''}{percentChange.toFixed(2)}%)
              </span>
                </p>
            )}
            <p className="flex justify-between mt-2 pt-2 border-t border-gray-200">
              <span className="mr-4 text-gray-600 font-medium">Volume:</span>
              <span className="font-semibold">{data.Volume.toLocaleString('id-ID')}</span>
            </p>
          </div>
        </div>
    );
  }

  return null;
};

// Custom label untuk ReferenceLine
const CustomLabel = ({ viewBox, value, position, fill, fontSize, fontWeight, backgroundColor, padding, chartType }) => {
  const { x, y, width, height } = viewBox;

  // Position logic
  let xPos, yPos, textAnchor;

  if (position === 'left') {
    xPos = x + 5;
    textAnchor = 'start';
  } else if (position === 'right') {
    xPos = x + width - 5;
    textAnchor = 'end';
  } else {
    xPos = x + width / 2;
    textAnchor = 'middle';
  }

  // Adjust y position based on chartType
  yPos = y - 10;

  return (
      <g>
        {/* Background rectangle for better readability */}
        <rect
            x={position === 'left' ? xPos - 2 : xPos - 80}
            y={yPos - 15}
            width={position === 'left' ? 160 : 80}
            height={20}
            fill={backgroundColor || 'white'}
            rx={4}
            ry={4}
            stroke="#e0e0e0"
            strokeWidth={1}
            opacity={0.9}
        />
        <text
            x={xPos}
            y={yPos}
            fill={fill || '#666'}
            textAnchor={textAnchor}
            fontSize={fontSize || 12}
            fontWeight={fontWeight || '500'}
            dominantBaseline="middle"
        >
          {value}
        </text>
      </g>
  );
};

const StockChart = ({ data, currencySymbol = 'Rp', chartType = 'composed' }) => {
  // State untuk menampilkan garis referensi
  const [showReferenceLines, setShowReferenceLines] = useState(true);

  // Pastikan data tidak kosong
  if (!data || data.length === 0) {
    return (
        <div className="chart-container p-4 bg-gray-100 rounded-lg">
          <p>Tidak ada data yang tersedia untuk ditampilkan</p>
        </div>
    );
  }

  // Persiapkan data untuk chart (urutkan berdasarkan tanggal)
  const sortedData = [...data].sort((a, b) => {
    const dateA = new Date(a.Date || a.Datetime);
    const dateB = new Date(b.Date || b.Datetime);
    return dateA - dateB; // Ascending order for chart
  });

  // Tambahkan informasi previousClose untuk perhitungan perubahan
  const chartData = sortedData.map((item, index) => {
    if (index === 0) {
      return {
        ...item,
        previousClose: null
      };
    }

    const previousClose = sortedData[index - 1].Close;

    return {
      ...item,
      previousClose
    };
  });

  // Fungsi untuk menentukan apakah menampilkan semua titik data
  const shouldShowAllTicks = chartData.length <= 30;

  // Format ticks pada sumbu X
  const formatXAxis = (tickItem) => {
    const date = new Date(tickItem);
    if (isNaN(date.getTime())) return tickItem;

    // Format singkat (DD/MM) jika banyak data
    if (chartData.length > 30) {
      return date.toLocaleDateString('id-ID', {
        day: '2-digit',
        month: '2-digit'
      });
    }

    // Format lengkap jika sedikit data
    return date.toLocaleDateString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: '2-digit'
    });
  };

  // Cari nilai min dan max untuk sumbu Y
  const minValue = Math.min(...chartData.map(item => item.Low));
  const maxValue = Math.max(...chartData.map(item => item.High));

  // Tambahkan sedikit margin untuk visualisasi yang lebih baik
  const yAxisDomain = [
    minValue - (minValue * 0.01), // 1% lebih rendah dari minimum
    maxValue + (maxValue * 0.01)  // 1% lebih tinggi dari maksimum
  ];

  // Dapatkan data harga terakhir dan perubahan
  const firstPrice = chartData[0]?.Close || 0;
  const lastPrice = chartData[chartData.length - 1]?.Close || 0;
  const movingAverage50 = chartData.length >= 50 ?
      chartData.slice(-50).reduce((sum, item) => sum + item.Close, 0) / 50 : null;
  const movingAverage200 = chartData.length >= 200 ?
      chartData.slice(-200).reduce((sum, item) => sum + item.Close, 0) / 200 : null;
  const overallChange = lastPrice - firstPrice;
  const overallPercentChange = (overallChange / firstPrice) * 100;
  const isPositiveOverall = overallChange >= 0;

  // Mendapatkan tanggal terakhir
  const lastDate = chartData[chartData.length - 1]?.Date || '';

  // Temukan harga tertinggi dan terendah selama periode
  const highestPrice = Math.max(...chartData.map(item => item.High));
  const lowestPrice = Math.min(...chartData.map(item => item.Low));
  const highestDate = chartData.find(item => item.High === highestPrice)?.Date || '';
  const lowestDate = chartData.find(item => item.Low === lowestPrice)?.Date || '';

  // Common chart props for consistent styling
  const commonChartProps = {
    margin: {
      top: 20,
      right: 30,
      left: 20,
      bottom: 50
    }
  };

  // Common axis props
  const xAxisProps = {
    dataKey: "Date",
    tickFormatter: formatXAxis,
    tick: { fontSize: 12, fill: '#555' },
    interval: shouldShowAllTicks ? 0 : 'preserveStartEnd',
    angle: -45,
    textAnchor: "end",
    height: 70,
    axisLine: { stroke: '#e0e0e0' },
    tickLine: { stroke: '#e0e0e0' }
  };

  const yAxisProps = {
    domain: yAxisDomain,
    tickFormatter: (value) => formatCurrency(value, currencySymbol),
    tick: { fontSize: 12, fill: '#555' },
    width: 90,
    axisLine: { stroke: '#e0e0e0' },
    tickLine: { stroke: '#e0e0e0' }
  };

  // Common grid props
  const gridProps = {
    strokeDasharray: "3 3",
    stroke: "#f0f0f0",
    vertical: false
  };

  // Common tooltip props
  const tooltipProps = {
    content: <CustomTooltip currencySymbol={currencySymbol} />,
    animationDuration: 300,
    animationEasing: "ease-out"
  };

  // Common legend props
  const legendProps = {
    verticalAlign: "top",
    height: 50,
    iconSize: 12,
    iconType: "circle",
    wrapperStyle: {
      paddingBottom: '15px',
      fontSize: '14px',
      fontWeight: '500'
    }
  };

  // Common brush props
  const brushProps = {
    dataKey: "Date",
    height: 35,
    stroke: isPositiveOverall ? '#4CAF50' : '#E53935',
    tickFormatter: formatXAxis,
    startIndex: Math.max(0, chartData.length - Math.min(60, chartData.length)),
    fill: "#ffffff",
    travellerWidth: 10,
    y: 5
  };

  // Improved reference line props using custom label component
  const refLineProps = {
    initial: {
      y: firstPrice,
      stroke: "#666",
      strokeDasharray: "3 3",
      strokeWidth: 1.5,
      label: (props) => (
          <CustomLabel
              {...props}
              value={`Awal: ${formatCurrency(firstPrice, currencySymbol)}`}
              position='left'
              fill='#555'
              fontSize={12}
              fontWeight='500'
              backgroundColor='white'
              padding={5}
              chartType={chartType}
          />
      )
    },
    highest: {
      y: highestPrice,
      stroke: "#2E7D32",
      strokeDasharray: "5 2",
      strokeWidth: 1.5,
      label: (props) => (
          <CustomLabel
              {...props}
              value={`Tertinggi: ${formatCurrency(highestPrice, currencySymbol)}`}
              position='right'
              fill='#2E7D32'
              fontSize={12}
              fontWeight='600'
              backgroundColor='rgba(76, 175, 80, 0.1)'
              padding={5}
              chartType={chartType}
          />
      )
    },
    lowest: {
      y: lowestPrice,
      stroke: "#C62828",
      strokeDasharray: "5 2",
      strokeWidth: 1.5,
      label: (props) => (
          <CustomLabel
              {...props}
              value={`Terendah: ${formatCurrency(lowestPrice, currencySymbol)}`}
              position='right'
              fill='#C62828'
              fontSize={12}
              fontWeight='600'
              backgroundColor='rgba(229, 57, 53, 0.1)'
              padding={5}
              chartType={chartType}
          />
      )
    },
    ma50: movingAverage50 ? {
      y: movingAverage50,
      stroke: "#1976D2",
      strokeWidth: 1.5,
      strokeDasharray: "3 3",
      label: (props) => (
          <CustomLabel
              {...props}
              value={`MA50: ${formatCurrency(movingAverage50, currencySymbol)}`}
              position='left'
              fill='#1976D2'
              fontSize={12}
              fontWeight='500'
              backgroundColor='rgba(25, 118, 210, 0.1)'
              padding={5}
              chartType={chartType}
          />
      )
    } : null,
    ma200: movingAverage200 ? {
      y: movingAverage200,
      stroke: "#8E24AA",
      strokeWidth: 1.5,
      strokeDasharray: "3 3",
      label: (props) => (
          <CustomLabel
              {...props}
              value={`MA200: ${formatCurrency(movingAverage200, currencySymbol)}`}
              position='left'
              fill='#8E24AA'
              fontSize={12}
              fontWeight='500'
              backgroundColor='rgba(142, 36, 170, 0.1)'
              padding={5}
              chartType={chartType}
          />
      )
    } : null
  };

  return (
      <div className="chart-container p-4 bg-gray-100 rounded-xl shadow-sm">
        {/* Panel harga terakhir yang lebih menonjol */}
        <div className="flex justify-between items-center p-5 bg-white rounded-xl shadow-md mb-6"
             style={{
               border: `1px solid ${isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)'}`,
               background: `linear-gradient(to right, white, ${isPositiveOverall ? 'rgba(76, 175, 80, 0.05)' : 'rgba(229, 57, 53, 0.05)'})`
             }}>
          <div>
            <div className="text-sm text-gray-600 mb-2 font-medium flex items-center">
            <span className="inline-block w-2 h-2 rounded-full mr-2"
                  style={{ backgroundColor: isPositiveOverall ? '#4CAF50' : '#E53935' }}></span>
              {formatDate(lastDate)} - Harga Terakhir
            </div>
            <div className="text-2xl font-bold tracking-tight"
                 style={{ color: isPositiveOverall ? '#2E7D32' : '#C62828' }}>
              {formatCurrency(lastPrice, currencySymbol)}
            </div>
          </div>
          <div className="text-right p-3 rounded-lg"
               style={{ backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)' }}>
            <div className="text-sm text-gray-600 mb-2 font-medium">
              Perubahan
            </div>
            <div className="flex flex-col items-end font-bold text-xl"
                 style={{ color: isPositiveOverall ? '#2E7D32' : '#C62828' }}>
              <div>
                {isPositiveOverall ? '+' : ''}{formatCurrency(overallChange, currencySymbol)}
              </div>
              <div className="text-base mt-1 px-2 py-1 rounded"
                   style={{ backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)' }}>
                {isPositiveOverall ? '+' : ''}{overallPercentChange.toFixed(2)}%
              </div>
            </div>
          </div>
        </div>

        {/* Toggle untuk reference lines */}
        <div className="mb-4 flex items-center">
          <button
              onClick={() => setShowReferenceLines(!showReferenceLines)}
              className="px-3 py-2 rounded-lg text-sm font-medium"
              style={{
                backgroundColor: showReferenceLines ? 'rgba(33, 150, 243, 0.1)' : 'rgba(0, 0, 0, 0.05)',
                color: showReferenceLines ? '#1976D2' : '#666',
                border: showReferenceLines ? '1px solid rgba(33, 150, 243, 0.3)' : '1px solid rgba(0, 0, 0, 0.1)'
              }}
          >
            {showReferenceLines ? '✓ Tampilkan Garis Referensi' : '○ Tampilkan Garis Referensi'}
          </button>

          <div className="ml-4 text-xs text-gray-500">
            {showReferenceLines &&
                <div className="flex items-center flex-wrap gap-3">
              <span className="flex items-center">
                <span className="inline-block w-4 h-1 bg-gray-600 mr-1"></span>
                Awal
              </span>
                  <span className="flex items-center">
                <span className="inline-block w-4 h-1 bg-green-700 mr-1"></span>
                Tertinggi
              </span>
                  <span className="flex items-center">
                <span className="inline-block w-4 h-1 bg-red-700 mr-1"></span>
                Terendah
              </span>
                  {movingAverage50 &&
                      <span className="flex items-center">
                  <span className="inline-block w-4 h-1 bg-blue-600 mr-1"></span>
                  MA50
                </span>
                  }
                  {movingAverage200 &&
                      <span className="flex items-center">
                  <span className="inline-block w-4 h-1 bg-purple-600 mr-1"></span>
                  MA200
                </span>
                  }
                </div>
            }
          </div>
        </div>

        <div className="relative bg-white rounded-xl p-6 shadow-md"
             style={{
               border: `1px solid ${isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)'}`,
             }}>
          <ResponsiveContainer width="100%" height={450}>
            {chartType === 'line' ? (
                <LineChart
                    data={chartData}
                    {...commonChartProps}
                >
                  <CartesianGrid {...gridProps} />
                  <XAxis {...xAxisProps} />
                  <YAxis {...yAxisProps} />
                  <Tooltip {...tooltipProps} />
                  <Legend {...legendProps} />

                  {/* Garis utama */}
                  <Line
                      type="monotone"
                      dataKey="Close"
                      name="Harga Penutupan"
                      stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      strokeWidth={2.5}
                      dot={{ r: 2, fill: isPositiveOverall ? '#4CAF50' : '#E53935', strokeWidth: 1, stroke: 'white' }}
                      activeDot={{
                        r: 7,
                        fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                        stroke: 'white',
                        strokeWidth: 2
                      }}
                      animationDuration={1500}
                      animationEasing="ease-in-out"
                  />

                  {/* Reference lines dengan props yang lebih optimal */}
                  {showReferenceLines && (
                      <>
                        <ReferenceLine {...refLineProps.initial} />
                        <ReferenceLine {...refLineProps.highest} />
                        <ReferenceLine {...refLineProps.lowest} />
                        {refLineProps.ma50 && <ReferenceLine {...refLineProps.ma50} />}
                        {refLineProps.ma200 && <ReferenceLine {...refLineProps.ma200} />}
                      </>
                  )}

                  <Brush {...brushProps} />
                </LineChart>
            ) : chartType === 'area' ? (
                <AreaChart
                    data={chartData}
                    {...commonChartProps}
                >
                  <defs>
                    <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                      <stop
                          offset="5%"
                          stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                          stopOpacity={0.25}
                      />
                      <stop
                          offset="95%"
                          stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                          stopOpacity={0}
                      />
                    </linearGradient>
                  </defs>
                  <CartesianGrid {...gridProps} />
                  <XAxis {...xAxisProps} />
                  <YAxis {...yAxisProps} />
                  <Tooltip {...tooltipProps} />
                  <Legend {...legendProps} />

                  {/* Area untuk visualisasi */}
                  <Area
                      type="monotone"
                      dataKey="Close"
                      name="Area Harga"
                      fill="url(#colorClose)"
                      stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      strokeWidth={2}
                      animationDuration={1500}
                      animationEasing="ease-in-out"
                  />

                  {/* Reference lines dengan props yang lebih optimal */}
                  {showReferenceLines && (
                      <>
                        <ReferenceLine {...refLineProps.initial} />
                        <ReferenceLine {...refLineProps.highest} />
                        <ReferenceLine {...refLineProps.lowest} />
                        {refLineProps.ma50 && <ReferenceLine {...refLineProps.ma50} />}
                        {refLineProps.ma200 && <ReferenceLine {...refLineProps.ma200} />}
                      </>
                  )}

                  <Brush {...brushProps} />
                </AreaChart>
            ) : (
                <ComposedChart
                    data={chartData}
                    {...commonChartProps}
                >
                  <defs>
                    <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                      <stop
                          offset="5%"
                          stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                          stopOpacity={0.25}
                      />
                      <stop
                          offset="95%"
                          stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                          stopOpacity={0}
                      />
                    </linearGradient>
                  </defs>
                  <CartesianGrid {...gridProps} />
                  <XAxis {...xAxisProps} />
                  <YAxis {...yAxisProps} />
                  <Tooltip {...tooltipProps} />
                  <Legend {...legendProps} />

                  {/* Area di bawah garis untuk visualisasi lebih baik */}
                  <Area
                      type="monotone"
                      dataKey="Close"
                      name="Area Harga"
                      fill="url(#colorClose)"
                      stroke="none"
                      animationDuration={1500}
                      animationEasing="ease-in-out"
                  />

                  {/* Garis utama */}
                  <Line
                      type="monotone"
                      dataKey="Close"
                      name="Harga Penutupan"
                      stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      strokeWidth={2.5}
                      dot={{ r: 2, fill: isPositiveOverall ? '#4CAF50' : '#E53935', strokeWidth: 1, stroke: 'white' }}
                      activeDot={{
                        r: 7,
                        fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                        stroke: 'white',
                        strokeWidth: 2
                      }}
                      animationDuration={1500}
                      animationEasing="ease-in-out"
                  />

                  {/* Reference lines dengan props yang lebih optimal */}
                  {showReferenceLines && (
                      <>
                        <ReferenceLine {...refLineProps.initial} />
                        <ReferenceLine {...refLineProps.highest} />
                        <ReferenceLine {...refLineProps.lowest} />
                        {refLineProps.ma50 && <ReferenceLine {...refLineProps.ma50} />}
                        {refLineProps.ma200 && <ReferenceLine {...refLineProps.ma200} />}
                      </>
                  )}

                  <Brush {...brushProps} />
                </ComposedChart>
            )}
          </ResponsiveContainer>
        </div>

        {/* Data overview */}
        <div className="mt-4 grid grid-cols-2 gap-4 sm:grid-cols-4">
          <div className="bg-white p-3 rounded-lg shadow-sm text-center">
            <div className="text-xs text-gray-500 mb-1">Harga Awal</div>
            <div className="font-semibold text-base">{formatCurrency(firstPrice, currencySymbol)}</div>
          </div>
          <div className="bg-white p-3 rounded-lg shadow-sm text-center">
            <div className="text-xs text-gray-500 mb-1">Tertinggi</div>
            <div className="font-semibold text-base text-green-700">{formatCurrency(highestPrice, currencySymbol)}</div>
            <div className="text-xs text-gray-500">{formatDate(highestDate)}</div>
          </div>
          <div className="bg-white p-3 rounded-lg shadow-sm text-center">
            <div className="text-xs text-gray-500 mb-1">Terendah</div>
            <div className="font-semibold text-base text-red-700">{formatCurrency(lowestPrice, currencySymbol)}</div>
            <div className="text-xs text-gray-500">{formatDate(lowestDate)}</div>
          </div>
          <div className="bg-white p-3 rounded-lg shadow-sm text-center">
            <div className="text-xs text-gray-500 mb-1">Rata-rata</div>
            <div className="font-semibold text-base text-blue-700">
              {formatCurrency(chartData.reduce((acc, item) => acc + item.Close, 0) / chartData.length, currencySymbol)}
            </div>
          </div>
        </div>
      </div>
  );
};

export default StockChart;
